diff --git a/supabase/migrations/20261103_regla_proveedor_tipo.sql b/supabase/migrations/20261103_regla_proveedor_tipo.sql
new file mode 100644
index 0000000..793e578
--- /dev/null
+++ b/supabase/migrations/20261103_regla_proveedor_tipo.sql
@@ -0,0 +1,118 @@
+-- Regla de impacto por proveedor y tipo de comprobante (SIN APLICAR: requiere confirmación de Ly).
+-- Si no existe regla para (proveedor, tipo), el comprobante va a Revisión (no hay valor por defecto).
+
+CREATE TABLE IF NOT EXISTS public.regla_impacto_proveedor (
+  id_proveedor      integer NOT NULL REFERENCES public.proveedores(id_proveedor),
+  tipo_comprobante  text    NOT NULL REFERENCES public.tipos_comprobante(nombre),
+  afecta_cta_cte    boolean NOT NULL,
+  afecta_stock      boolean NOT NULL,
+  actualizado_por   text,
+  actualizado_at    timestamptz NOT NULL DEFAULT now(),
+  PRIMARY KEY (id_proveedor, tipo_comprobante)
+);
+
+-- Historial de cada corrección (nada se borra).
+CREATE TABLE IF NOT EXISTS public.regla_impacto_historial (
+  id                bigserial PRIMARY KEY,
+  id_proveedor      integer NOT NULL,
+  tipo_comprobante  text    NOT NULL,
+  antes_cta_cte     boolean,
+  despues_cta_cte   boolean NOT NULL,
+  antes_stock       boolean,
+  despues_stock     boolean NOT NULL,
+  usuario           text,
+  motivo            text,
+  fecha             timestamptz NOT NULL DEFAULT now()
+);
+
+-- Flag de manuscrito por archivo de Drive.
+ALTER TABLE public.archivos_procesados ADD COLUMN IF NOT EXISTS manuscrito boolean NOT NULL DEFAULT false;
+
+-- Compuertas de clasificación (sin efectos: solo decide el destino).
+-- Destinos: PROCESADO (comprobante), LISTA (lista de precios), REVISION (con motivo).
+CREATE OR REPLACE FUNCTION public.clasificar_documento(
+  p_proveedor integer, p_tipo text, p_fecha date, p_numero text, p_total numeric,
+  p_es_lista boolean DEFAULT false, p_ultima_lista date DEFAULT NULL)
+RETURNS TABLE(destino text, motivo text, afecta_cta_cte boolean, afecta_stock boolean)
+LANGUAGE plpgsql STABLE AS $$
+declare r regla_impacto_proveedor%rowtype; prov_ok boolean; tipo_ok boolean;
+begin
+  select (estado = 'ACTIVO') into prov_ok from proveedores where id_proveedor = p_proveedor;
+  if p_es_lista then
+    if coalesce(prov_ok,false) = false then return query select 'REVISION','proveedor_no_existe',null::boolean,null::boolean; return; end if;
+    if p_fecha is null then return query select 'REVISION','sin_fecha',null::boolean,null::boolean; return; end if;
+    if p_ultima_lista is not null and p_fecha <= p_ultima_lista then
+      return query select 'REVISION','fecha_menor_a_ultima_lista',null::boolean,null::boolean; return; end if;
+    return query select 'LISTA','ok',null::boolean,null::boolean; return;
+  end if;
+  if coalesce(prov_ok,false) = false then return query select 'REVISION','proveedor_no_existe_o_no_aprobado',null::boolean,null::boolean; return; end if;
+  select exists(select 1 from tipos_comprobante where nombre = p_tipo and activo) into tipo_ok;
+  if not tipo_ok then return query select 'REVISION','tipo_no_autorizado',null::boolean,null::boolean; return; end if;
+  if p_numero is null or p_fecha is null or p_total is null then
+    return query select 'REVISION','faltan_datos_obligatorios',null::boolean,null::boolean; return; end if;
+  select * into r from regla_impacto_proveedor where id_proveedor = p_proveedor and tipo_comprobante = p_tipo;
+  if not found then return query select 'REVISION','sin_regla_proveedor_tipo',null::boolean,null::boolean; return; end if;
+  return query select 'PROCESADO','ok', r.afecta_cta_cte, r.afecta_stock;
+end $$;
+
+-- Corrección de impacto de un comprobante (cta cte y stock). Nada se borra: se registra contramovimiento,
+-- se actualiza la regla proveedor+tipo (memoria) y se deja historial.
+CREATE OR REPLACE FUNCTION public.corregir_impacto_comprobante(p_id integer, p_cta boolean, p_stock boolean, p_usuario text, p_motivo text DEFAULT NULL)
+RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
+declare
+  c comprobantes_compra%rowtype; mov text; sgn integer; prev numeric; nuevo numeric;
+  m record; cnt integer := 0; delta numeric; ant_cc boolean; ant_st boolean; ref text; st_res numeric;
+begin
+  select * into c from comprobantes_compra where id_comprobante = p_id for update;
+  if not found then raise exception 'Comprobante inexistente'; end if;
+  if c.imputa_cta_cte is not distinct from p_cta and c.imputa_stock is not distinct from p_stock then
+    return jsonb_build_object('estado','sin_cambios');
+  end if;
+  select coalesce(movimiento,'debe') into mov from tipos_comprobante where nombre = c.tipo_comprobante;
+  sgn := case when mov = 'haber' then -1 else 1 end;
+  ref := c.numero_comprobante;
+
+  -- 1) Reversa de cuenta corriente si estaba aplicada y se quita.
+  if c.imputa_cta_cte is true and p_cta is distinct from true and c.cta_cte_aplicada_at is not null then
+    select coalesce((select saldo_resultante from movimientos_cuenta_proveedor where id_proveedor = c.id_proveedor order by fecha_registro desc, id_movimiento_cc desc limit 1), 0) into prev;
+    nuevo := prev - sgn * c.total_comprobante;
+    insert into movimientos_cuenta_proveedor (id_proveedor, tipo, concepto, referencia_id, importe, saldo_resultante, usuario_responsable, fecha_operacion, fecha_registro, es_credito)
+    values (c.id_proveedor, case when sgn > 0 then 'CREDITO' else 'DEBITO' end, 'Corrección reversa ' || ref, ref, c.total_comprobante, nuevo, p_usuario, current_date, now(), false);
+    insert into cuentas_proveedor (id_proveedor, saldo_deuda, fecha_actualizacion) values (c.id_proveedor, nuevo, now())
+      on conflict (id_proveedor) do update set saldo_deuda = excluded.saldo_deuda, fecha_actualizacion = now();
+    update comprobantes_compra set cta_cte_aplicada_at = null where id_comprobante = p_id;
+  end if;
+
+  -- 2) Aplicación de cuenta corriente si se agrega.
+  if p_cta is true and c.imputa_cta_cte is distinct from true then
+    select coalesce((select saldo_resultante from movimientos_cuenta_proveedor where id_proveedor = c.id_proveedor order by fecha_registro desc, id_movimiento_cc desc limit 1), 0) into prev;
+    nuevo := prev + sgn * c.total_comprobante;
+    insert into movimientos_cuenta_proveedor (id_proveedor, tipo, concepto, referencia_id, importe, saldo_resultante, usuario_responsable, fecha_operacion, fecha_registro, es_credito)
+    values (c.id_proveedor, case when sgn > 0 then 'DEBITO' else 'CREDITO' end, 'Corrección aplicada ' || ref, ref, c.total_comprobante, nuevo, p_usuario, current_date, now(), false);
+    insert into cuentas_proveedor (id_proveedor, saldo_deuda, fecha_actualizacion) values (c.id_proveedor, nuevo, now())
+      on conflict (id_proveedor) do update set saldo_deuda = excluded.saldo_deuda, fecha_actualizacion = now();
+    update comprobantes_compra set cta_cte_aplicada_at = now() where id_comprobante = p_id;
+  end if;
+
+  -- 3) Reversa de stock de los ingresos ya registrados por este comprobante, si se quita.
+  if c.imputa_stock is true and p_stock is distinct from true then
+    for m in select * from movimientos_stock where origen = 'COMPRA' and referencia_id = p_id::text loop
+      delta := case when m.tipo_movimiento = 'ENTRADA' then -m.cantidad else m.cantidad end;
+      update productos set stock_actual = stock_actual + delta where id_producto = m.id_producto returning stock_actual into st_res;
+      insert into movimientos_stock (id_producto, tipo_movimiento, cantidad, stock_resultante, origen, referencia_id, usuario_responsable, fecha_registro)
+      values (m.id_producto, case when delta < 0 then 'SALIDA' else 'ENTRADA' end, abs(m.cantidad), st_res, 'REVERSA_COMPRA', p_id::text, p_usuario, now());
+      cnt := cnt + 1;
+    end loop;
+  end if;
+
+  -- 4) Flags del comprobante, memoria proveedor+tipo e historial.
+  select afecta_cta_cte, afecta_stock into ant_cc, ant_st from regla_impacto_proveedor where id_proveedor = c.id_proveedor and tipo_comprobante = c.tipo_comprobante;
+  update comprobantes_compra set imputa_cta_cte = p_cta, imputa_stock = p_stock where id_comprobante = p_id;
+  insert into regla_impacto_proveedor (id_proveedor, tipo_comprobante, afecta_cta_cte, afecta_stock, actualizado_por, actualizado_at)
+  values (c.id_proveedor, c.tipo_comprobante, p_cta, p_stock, p_usuario, now())
+  on conflict (id_proveedor, tipo_comprobante) do update set afecta_cta_cte = excluded.afecta_cta_cte, afecta_stock = excluded.afecta_stock, actualizado_por = excluded.actualizado_por, actualizado_at = now();
+  insert into regla_impacto_historial (id_proveedor, tipo_comprobante, antes_cta_cte, despues_cta_cte, antes_stock, despues_stock, usuario, motivo)
+  values (c.id_proveedor, c.tipo_comprobante, ant_cc, p_cta, ant_st, p_stock, p_usuario, coalesce(p_motivo, 'corrección comprobante ' || p_id));
+
+  return jsonb_build_object('estado','corregido','reversas_stock',cnt,'cta_cte',p_cta,'stock',p_stock);
+end $$;
diff --git a/supabase/migrations/20261104_accion_cta_stock_por_proveedor_tipo.sql b/supabase/migrations/20261104_accion_cta_stock_por_proveedor_tipo.sql
new file mode 100644
index 0000000..8a36a6c
--- /dev/null
+++ b/supabase/migrations/20261104_accion_cta_stock_por_proveedor_tipo.sql
@@ -0,0 +1,18 @@
+-- SIN APLICAR: requiere confirmación de Ly.
+-- Acción de cuenta corriente y de stock por proveedor + tipo, con los mismos valores del desplegable:
+--   suma | resta | sin_accion. El signo sale de esta acción, no del campo movimiento del tipo.
+-- Sin valor (NULL) = sin regla: el comprobante va a Revisión.
+-- No se hace backfill desde afecta_cta_cte / afecta_stock: esos booleanos no distinguen suma de resta.
+
+ALTER TABLE public.regla_impacto_proveedor
+  ADD COLUMN IF NOT EXISTS accion_cta_cte text
+    CHECK (accion_cta_cte IN ('suma','resta','sin_accion')),
+  ADD COLUMN IF NOT EXISTS accion_stock text
+    CHECK (accion_stock IN ('suma','resta','sin_accion'));
+
+-- PENDIENTE, NO INCLUIDO (esta migración por sí sola no cambia ningún comportamiento):
+-- 1) clasificar_documento: exigir accion_cta_cte y accion_stock no nulos; si faltan -> REVISION.
+-- 2) corregir_impacto_comprobante: el signo de cuenta corriente sale de accion_cta_cte
+--    (suma = +1, resta = -1, sin_accion = no imputa). Hace falta guardar el signo aplicado
+--    en cada comprobante, para que la reversa use el mismo signo que la aplicación original.
+-- 3) Comprobantes ya cargados: no se reescriben.
diff --git a/supabase/migrations/20261105_funciones_accion_cta_stock.sql b/supabase/migrations/20261105_funciones_accion_cta_stock.sql
new file mode 100644
index 0000000..9b70e3e
--- /dev/null
+++ b/supabase/migrations/20261105_funciones_accion_cta_stock.sql
@@ -0,0 +1,138 @@
+-- SIN APLICAR: requiere confirmación de Ly.
+-- Depende de 20261104_accion_cta_stock_por_proveedor_tipo.sql (columnas accion_cta_cte / accion_stock).
+-- Pasos 1 y 2 del handoff:
+--   1) clasificar_documento exige acciones no nulas por proveedor+tipo; si falta alguna -> REVISION.
+--   2) corregir_impacto_comprobante toma el signo de accion_cta_cte (suma=+1, resta=-1) y lo guarda
+--      por comprobante (signo_cta_cte) para que la reversa use exactamente el mismo signo.
+--      La firma no cambia: p_cta / p_stock siguen siendo booleanos.
+-- Comprobantes ya aplicados sin signo guardado: la reversa usa el signo legado (movimiento del tipo).
+
+ALTER TABLE public.comprobantes_compra
+  ADD COLUMN IF NOT EXISTS signo_cta_cte smallint
+    CHECK (signo_cta_cte IN (1, -1));
+
+-- Fijar acciones (desplegable suma | resta | sin_accion) para un proveedor + tipo. Registra historial.
+CREATE OR REPLACE FUNCTION public.fijar_accion_proveedor_tipo(
+  p_id_proveedor integer, p_tipo text, p_accion_cta text, p_accion_stock text, p_usuario text, p_motivo text DEFAULT NULL)
+RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
+declare ant regla_impacto_proveedor%rowtype; ant_found boolean;
+begin
+  if p_accion_cta not in ('suma','resta','sin_accion') or p_accion_stock not in ('suma','resta','sin_accion') then
+    raise exception 'Acción inválida';
+  end if;
+  if not exists (select 1 from tipos_comprobante where nombre = p_tipo) then raise exception 'Tipo inexistente'; end if;
