+-- Compuertas de clasificación (sin efectos: solo decide el destino).
+-- Destinos: PROCESADO (comprobante), LISTA (lista de precios), REVISION (con motivo).
+CREATE OR REPLACE FUNCTION public.clasificar_documento(
+  p_proveedor integer, p_tipo text, p_fecha date, p_numero text, p_total numeric,
+  p_es_lista boolean DEFAULT false, p_ultima_lista date DEFAULT NULL)
+RETURNS TABLE(destino text, motivo text, afecta_cta_cte boolean, afecta_stock boolean)
+LANGUAGE plpgsql STABLE AS $$
+declare r regla_impacto_proveedor%rowtype; prov_ok boolean; tipo_ok boolean;
+begin
+  select (estado = 'ACTIVO') into prov_ok from proveedores where id_proveedor = p_proveedor;
+  if p_es_lista then
+    if coalesce(prov_ok,false) = false then return query select 'REVISION','proveedor_no_existe',null::boolean,null::boolean; return; end if;
+    if p_fecha is null then return query select 'REVISION','sin_fecha',null::boolean,null::boolean; return; end if;
+    if p_ultima_lista is not null and p_fecha <= p_ultima_lista then
+      return query select 'REVISION','fecha_menor_a_ultima_lista',null::boolean,null::boolean; return; end if;
+    return query select 'LISTA','ok',null::boolean,null::boolean; return;
+  end if;
+  if coalesce(prov_ok,false) = false then return query select 'REVISION','proveedor_no_existe_o_no_aprobado',null::boolean,null::boolean; return; end if;
+  select exists(select 1 from tipos_comprobante where nombre = p_tipo and activo) into tipo_ok;
+  if not tipo_ok then return query select 'REVISION','tipo_no_autorizado',null::boolean,null::boolean; return; end if;
+  if p_numero is null or p_fecha is null or p_total is null then
+    return query select 'REVISION','faltan_datos_obligatorios',null::boolean,null::boolean; return; end if;
+  select * into r from regla_impacto_proveedor where id_proveedor = p_proveedor and tipo_comprobante = p_tipo;
+  if not found then return query select 'REVISION','sin_regla_proveedor_tipo',null::boolean,null::boolean; return; end if;
+  if r.accion_cta_cte is null or r.accion_stock is null then
+    return query select 'REVISION','sin_accion_proveedor_tipo',null::boolean,null::boolean; return; end if;
+  return query select 'PROCESADO','ok', (r.accion_cta_cte <> 'sin_accion'), (r.accion_stock <> 'sin_accion');
+end $$;
