+  acc_cta text;
+begin
+  select * into c from comprobantes_compra where id_comprobante = p_id for update;
+  if not found then raise exception 'Comprobante inexistente'; end if;
+  if c.imputa_cta_cte is not distinct from p_cta and c.imputa_stock is not distinct from p_stock then
+    return jsonb_build_object('estado','sin_cambios');
+  end if;
+  ref := c.numero_comprobante;
+
+  -- Signo de aplicación: sale de la acción registrada por proveedor + tipo.
+  select accion_cta_cte into acc_cta from regla_impacto_proveedor where id_proveedor = c.id_proveedor and tipo_comprobante = c.tipo_comprobante;
+  if p_cta is true and acc_cta not in ('suma','resta') then
+    raise exception 'Sin acción de cuenta corriente para proveedor % tipo %', c.id_proveedor, c.tipo_comprobante;
+  end if;
+  sgn := case when acc_cta = 'resta' then -1 else 1 end;
+
+  -- Signo a revertir: el guardado en el comprobante; si no hay (aplicado antes de esta regla), el legado por movimiento del tipo.
+  select coalesce(movimiento,'debe') into mov from tipos_comprobante where nombre = c.tipo_comprobante;
+  sgn_rev := coalesce(c.signo_cta_cte, case when mov = 'haber' then -1 else 1 end);
+
