+  if c.imputa_cta_cte is true and p_cta is distinct from true and c.cta_cte_aplicada_at is not null then
+    select coalesce((select saldo_resultante from movimientos_cuenta_proveedor where id_proveedor = c.id_proveedor order by fecha_registro desc, id_movimiento_cc desc limit 1), 0) into prev;
+    nuevo := prev - sgn_rev * c.total_comprobante;
+    insert into movimientos_cuenta_proveedor (id_proveedor, tipo, concepto, referencia_id, importe, saldo_resultante, usuario_responsable, fecha_operacion, fecha_registro, es_credito)
+    values (c.id_proveedor, case when sgn_rev > 0 then 'CREDITO' else 'DEBITO' end, 'Corrección reversa ' || ref, ref, c.total_comprobante, nuevo, p_usuario, current_date, now(), false);
+    insert into cuentas_proveedor (id_proveedor, saldo_deuda, fecha_actualizacion) values (c.id_proveedor, nuevo, now())
+      on conflict (id_proveedor) do update set saldo_deuda = excluded.saldo_deuda, fecha_actualizacion = now();
+    update comprobantes_compra set cta_cte_aplicada_at = null, signo_cta_cte = null where id_comprobante = p_id;
+  end if;
+
+  -- 2) Aplicación de cuenta corriente si se agrega (signo de la acción suma/resta).
+  if p_cta is true and c.imputa_cta_cte is distinct from true then
+    select coalesce((select saldo_resultante from movimientos_cuenta_proveedor where id_proveedor = c.id_proveedor order by fecha_registro desc, id_movimiento_cc desc limit 1), 0) into prev;
+    nuevo := prev + sgn * c.total_comprobante;
+    insert into movimientos_cuenta_proveedor (id_proveedor, tipo, concepto, referencia_id, importe, saldo_resultante, usuario_responsable, fecha_operacion, fecha_registro, es_credito)
+    values (c.id_proveedor, case when sgn > 0 then 'DEBITO' else 'CREDITO' end, 'Corrección aplicada ' || ref, ref, c.total_comprobante, nuevo, p_usuario, current_date, now(), false);
+    insert into cuentas_proveedor (id_proveedor, saldo_deuda, fecha_actualizacion) values (c.id_proveedor, nuevo, now())
+      on conflict (id_proveedor) do update set saldo_deuda = excluded.saldo_deuda, fecha_actualizacion = now();
+    update comprobantes_compra set cta_cte_aplicada_at = now(), signo_cta_cte = sgn where id_comprobante = p_id;
+  end if;
+
+  -- 3) Reversa de stock de los ingresos ya registrados por este comprobante, si se quita.
+  if c.imputa_stock is true and p_stock is distinct from true then
+    for m in select * from movimientos_stock where origen = 'COMPRA' and referencia_id = p_id::text loop
+      delta := case when m.tipo_movimiento = 'ENTRADA' then -m.cantidad else m.cantidad end;
