import { redirect } from "next/navigation";
import { usuarioActual } from "@/lib/supabase/server";
import RevisionCliente from "./revision-cliente";
import ComprobantesCargados, { type CompCargado } from "./comprobantes-cargados";

export const dynamic = "force-dynamic";

export default async function RevisionPage() {
  const { user, rol, sb } = await usuarioActual();
  if (!user) redirect("/login");
  if (rol !== "administrador") redirect("/panel");

  const { data: archivos } = await sb
    .from("archivos_procesados")
    .select("id_archivo_drive, nombre, tipo_documento, numero_comprobante, fecha_documento, estado, id_proveedor, id_comprobante, fecha_registro, confianza, manuscrito")
    .eq("estado", "revision")
    .order("fecha_registro", { ascending: false });

  const { data: proveedores } = await sb
    .from("proveedores")
    .select("id_proveedor, razon_social, cuit")
    .ilike("estado", "activo")
    .order("razon_social");

  // Comprobantes cargados (estado CARGADO) con sus ítems. Si la columna nota_revision
  // todavía no existe (migración pendiente), se reintenta sin ella.
  const COMP = "id_comprobante, tipo_comprobante, numero_comprobante, fecha_comprobante, total_comprobante, id_proveedor, estado, proveedores(razon_social), items_compra(id_producto, estado_coincidencia)";
  let res: any = await sb.from("comprobantes_compra").select(`${COMP}, nota_revision`).in("estado", ["CARGADO", "REVISAR"]).order("fecha_comprobante").order("numero_comprobante");
  if (res.error) res = await sb.from("comprobantes_compra").select(COMP).in("estado", ["CARGADO", "REVISAR"]).order("fecha_comprobante").order("numero_comprobante");

  // Acción de cuenta y stock por proveedor + tipo (regla_impacto_proveedor). Sin fila completa = falta acción.
  // Si no se pueden leer las acciones, no se afirma que falten: no se muestran formularios para no pisar acciones existentes.
  const { data: reglasRaw, error: errReglas } = await sb.from("regla_impacto_proveedor").select("id_proveedor, tipo_comprobante, accion_cta_cte, accion_stock");
  const accionesOk = !errReglas;
  const reglas: any[] = reglasRaw ?? [];
  const conAccion = new Set(
    reglas.filter((r) => r.accion_cta_cte && r.accion_stock).map((r) => `${r.id_proveedor}|${r.tipo_comprobante}`)
  );

  const cargados: CompCargado[] = (res.data ?? []).map((c: any) => {
    const prov = Array.isArray(c.proveedores) ? c.proveedores[0] : c.proveedores;
    const items: any[] = c.items_compra ?? [];
    return {
      falta_accion: accionesOk && !conAccion.has(`${c.id_proveedor}|${c.tipo_comprobante}`),
      id_comprobante: c.id_comprobante,
      tipo_comprobante: c.tipo_comprobante,
      numero_comprobante: c.numero_comprobante,
      fecha_comprobante: c.fecha_comprobante,
      total_comprobante: c.total_comprobante,
      id_proveedor: c.id_proveedor,
      estado: c.estado,
      razon_social: prov?.razon_social ?? "—",
      nota_revision: c.nota_revision ?? null,
      items: items.length,
      sin_vincular: items.filter((i) => !i.id_producto && i.estado_coincidencia !== "DESCARTADO").length,
    };
  });

  return (
    <div className="space-y-8">
      <ComprobantesCargados comprobantes={cargados} errorAcciones={accionesOk ? null : "No se pudieron leer las acciones guardadas. No se pueden cargar acciones hasta recargar la página."} />
      <RevisionCliente archivos={archivos ?? []} proveedores={proveedores ?? []} />
    </div>
  );
}

import { createClient } from "@supabase/supabase-js";
import { NextResponse, type NextRequest } from "next/server";
import { usuarioActual } from "@/lib/supabase/server";

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);

const ACCIONES = ["suma", "resta", "sin_accion"] as const;
type Accion = (typeof ACCIONES)[number];
const esAccion = (v: unknown): v is Accion => ACCIONES.includes(v as Accion);

// POST /api/revision/accion
// body: { id_proveedor, tipo_comprobante, accion_cta_cte, accion_stock }
// Fija la acción de cuenta corriente y de stock para proveedor + tipo (función fijar_accion_proveedor_tipo).
// El nombre del tipo se usa tal cual viene del comprobante: no se normaliza ni se traduce.
export async function POST(req: NextRequest) {
  const { user, rol } = await usuarioActual();
  if (!user) return NextResponse.json({ error: "Sin sesión" }, { status: 401 });
  if (rol !== "administrador") return NextResponse.json({ error: "Sin permisos" }, { status: 403 });

  const b = (await req.json().catch(() => ({}))) as {
    id_proveedor?: number;
    tipo_comprobante?: string;
    accion_cta_cte?: unknown;
    accion_stock?: unknown;
  };
  const idProv = Number(b.id_proveedor);
  if (!Number.isInteger(idProv) || idProv <= 0) return NextResponse.json({ error: "Proveedor inválido" }, { status: 400 });
  if (!b.tipo_comprobante) return NextResponse.json({ error: "Falta el tipo de comprobante" }, { status: 400 });
  if (!esAccion(b.accion_cta_cte) || !esAccion(b.accion_stock)) {
    return NextResponse.json({ error: "Acción inválida (suma, resta o sin_accion)" }, { status: 400 });
  }

  const { data, error } = await supabase.rpc("fijar_accion_proveedor_tipo", {
    p_id_proveedor: idProv,
    p_tipo: b.tipo_comprobante,
    p_accion_cta: b.accion_cta_cte,
    p_accion_stock: b.accion_stock,
    p_usuario: user.email ?? user.id,
    p_motivo: null,
  });
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ ok: true, ...(typeof data === "object" && data ? data : {}) });
}

"use client";
import { useMemo, useState } from "react";

export type CompCargado = {
  id_comprobante: number;
