type Accion = "suma" | "resta" | "sin_accion";
const OPCIONES_ACCION: { value: Accion; label: string }[] = [
  { value: "suma", label: "Suma" },
  { value: "resta", label: "Resta" },
  { value: "sin_accion", label: "Sin acción" },
];

const money = (n: string) =>
  Number(n).toLocaleString("es-AR", { style: "currency", currency: "ARS", maximumFractionDigits: 0 });
