function Fila({
  c,
  onAprobado,
  onAccion,
}: {
  c: CompCargado;
  onAprobado: (id: number) => void;
  onAccion: (idProveedor: number, tipo: string) => void;
}) {
  const [accCta, setAccCta] = useState<Accion | "">("");
  const [accStock, setAccStock] = useState<Accion | "">("");
  const [guardandoAccion, setGuardandoAccion] = useState(false);
  const [errorAccion, setErrorAccion] = useState("");
  const [nota, setNota] = useState(c.nota_revision ?? "");
  const [guardada, setGuardada] = useState(c.nota_revision ?? "");
  const [estadoNota, setEstadoNota] = useState<"" | "guardando" | "ok" | "error">("");
  const [errorNota, setErrorNota] = useState("");
  const [aprobando, setAprobando] = useState(false);
  const [errorAprobar, setErrorAprobar] = useState("");

  const listo = c.sin_vincular === 0;

  async function guardarAccion() {
    if (!accCta || !accStock) return;
    setGuardandoAccion(true);
    setErrorAccion("");
    const r = await fetch("/api/revision/accion", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id_proveedor: c.id_proveedor,
        tipo_comprobante: c.tipo_comprobante,
        accion_cta_cte: accCta,
        accion_stock: accStock,
      }),
    });
    const j = await r.json().catch(() => ({}));
    setGuardandoAccion(false);
    if (!r.ok) { setErrorAccion(j.error ?? "No se pudo guardar la acción"); return; }
    onAccion(c.id_proveedor, c.tipo_comprobante);
  }

  async function guardar() {
    setEstadoNota("guardando");
    const r = await fetch("/api/revision/nota", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id_comprobante: c.id_comprobante, nota }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { setErrorNota(j.error ?? "Error"); setEstadoNota("error"); return; }
    setGuardada(nota.trim());
    setEstadoNota("ok");
  }

  async function aprobar() {
    setAprobando(true);
    setErrorAprobar("");
    const r = await fetch("/api/revision/aprobar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id_comprobante: c.id_comprobante }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { setErrorAprobar(j.error ?? "Error al aprobar"); setAprobando(false); return; }
    onAprobado(c.id_comprobante);
  }

  return (
    <div className="rounded-md border border-line bg-panel p-3 space-y-2">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <p className="font-semibold text-sm">{c.razon_social}</p>
          <p className="text-xs text-muted mt-0.5">
            {c.tipo_comprobante} {c.numero_comprobante} · {new Date(c.fecha_comprobante + "T00:00:00").toLocaleDateString("es-AR")}
            {" · "}{c.items} ítem{c.items !== 1 ? "s" : ""}
            {c.estado === "REVISAR" && <span className="text-amber-600 dark:text-amber-400"> · a revisar</span>}
            {c.sin_vincular > 0 && (
              <span className="text-amber-600 dark:text-amber-400"> · {c.sin_vincular} sin vincular</span>
            )}
            {listo && (
              <span className="text-green-600 dark:text-green-400"> · todos vinculados ✓</span>
            )}
          </p>
        </div>
        <p className="text-sm font-semibold">{money(c.total_comprobante)}</p>
      </div>

      {c.falta_accion && (
        <div className="rounded-md border border-amber-500/40 bg-amber-500/5 p-2 space-y-2">
          <p className="text-xs text-amber-700 dark:text-amber-400">
            Sin acción para este proveedor y tipo. La acción queda guardada para todos los comprobantes de {c.razon_social} con tipo {c.tipo_comprobante}.
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <label className="text-xs text-muted flex items-center gap-1.5">
              Cuenta corriente
              <select className={selAccion} value={accCta} onChange={(e) => setAccCta(e.target.value as Accion | "")}>
                <option value="">Elegí…</option>
                {OPCIONES_ACCION.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </label>
            <label className="text-xs text-muted flex items-center gap-1.5">
              Stock
              <select className={selAccion} value={accStock} onChange={(e) => setAccStock(e.target.value as Accion | "")}>
                <option value="">Elegí…</option>
                {OPCIONES_ACCION.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </label>
            <button className={btn} disabled={guardandoAccion || !accCta || !accStock} onClick={guardarAccion}>
              {guardandoAccion ? "Guardando…" : "Guardar acción"}
            </button>
            {errorAccion && <span className="text-xs text-red-500">{errorAccion}</span>}
          </div>
        </div>
      )}

      <textarea
        className="w-full rounded-md border border-line bg-panel px-3 py-2 text-sm outline-none focus:border-accent"
        rows={2}
        maxLength={2000}
        placeholder="Aclaración o solución a realizar con este comprobante…"
        value={nota}
        onChange={(e) => { setNota(e.target.value); setEstadoNota(""); }}
