      <div className="flex flex-wrap items-center gap-2">
        <button
          className={btn}
          disabled={estadoNota === "guardando" || nota.trim() === guardada}
          onClick={guardar}
        >
          {estadoNota === "guardando" ? "Guardando…" : "Guardar nota"}
        </button>

        {/* Ir a mapeo filtrado por proveedor */}
