        {/* Aprobar (solo si no hay ítems sin vincular) */}
        {listo && (
          <button className={btnGreen} disabled={aprobando} onClick={aprobar}>
            {aprobando ? "Aprobando…" : "✓ Aprobar"}
          </button>
        )}

        {estadoNota === "ok" && <span className="text-xs text-green-600 dark:text-green-400">✓ Nota guardada</span>}
        {estadoNota === "error" && <span className="text-xs text-red-500">{errorNota}</span>}
        {errorAprobar && <span className="text-xs text-red-500">{errorAprobar}</span>}
      </div>
    </div>
  );
}

export default function ComprobantesCargados({
  comprobantes: inicial,
  errorAcciones,
}: {
  comprobantes: CompCargado[];
  errorAcciones?: string | null;
}) {
  const [comprobantes, setComprobantes] = useState(inicial);
  const [tipo, setTipo] = useState("");
  const [prov, setProv] = useState("");
  const [acc, setAcc] = useState<"" | "falta" | "con">("");

  function handleAprobado(id: number) {
    setComprobantes((prev) => prev.filter((c) => c.id_comprobante !== id));
  }

  // Al guardar una acción, vale para todos los comprobantes de ese proveedor + tipo.
  function handleAccion(idProveedor: number, tipoComp: string) {
    setComprobantes((prev) =>
      prev.map((c) => (c.id_proveedor === idProveedor && c.tipo_comprobante === tipoComp ? { ...c, falta_accion: false } : c))
    );
  }

  const tipos = useMemo(() => Array.from(new Set(comprobantes.map((c) => c.tipo_comprobante))).sort(), [comprobantes]);
  const porTipo = useMemo(() => comprobantes.filter((c) => !tipo || c.tipo_comprobante === tipo), [comprobantes, tipo]);
  const provs = useMemo(() => {
    const m = new Map<number, string>();
    porTipo.forEach((c) => m.set(c.id_proveedor, c.razon_social));
    return Array.from(m.entries()).sort((a, b) => a[1].localeCompare(b[1]));
  }, [porTipo]);
  const visibles = useMemo(
    () =>
      porTipo
        .filter((c) => !prov || String(c.id_proveedor) === prov)
        .filter((c) => !acc || (acc === "falta" ? c.falta_accion : !c.falta_accion))
        .sort((a, b) => a.fecha_comprobante.localeCompare(b.fecha_comprobante) || a.numero_comprobante.localeCompare(b.numero_comprobante)),
    [porTipo, prov, acc]
  );

  if (!comprobantes.length) return null;
  const sinAccion = comprobantes.filter((c) => c.falta_accion).length;

  const listos = comprobantes.filter((c) => c.sin_vincular === 0).length;
  const sel = "rounded-md border border-line bg-panel px-3 py-1.5 text-sm outline-none focus:border-accent";

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 className="text-lg font-semibold">Comprobantes cargados para revisar</h2>
        <div className="flex items-center gap-2">
          {listos > 0 && (
            <span className="rounded-full bg-green-500/10 px-2.5 py-0.5 text-xs font-semibold text-green-700 dark:text-green-400">
              {listos} listos para aprobar
            </span>
          )}
          <span className="text-sm text-muted">{visibles.length} de {comprobantes.length}</span>
        </div>
