import { NextRequest, NextResponse } from "next/server";
import { usuarioActual } from "@/lib/supabase/server";

export async function POST(req: NextRequest) {
  const { user, rol, sb } = await usuarioActual();
  if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });
  if (rol !== "administrador") return NextResponse.json({ error: "Sin permiso" }, { status: 403 });

  const { id_comprobante } = await req.json();
  if (!id_comprobante) return NextResponse.json({ error: "id_comprobante requerido" }, { status: 400 });

  // Verificar que no queden ítems sin vincular
  const { data: check } = await sb
    .from("items_compra")
    .select("id_item")
    .eq("id_comprobante", id_comprobante)
    .is("id_producto", null)
    .not("estado_coincidencia", "in", '("CREAR_NUEVO","IGNORAR","DESCARTADO")')
    .limit(1);

  if (check && check.length > 0) {
    return NextResponse.json({ error: "El comprobante todavía tiene ítems sin vincular" }, { status: 422 });
  }

  const { error } = await sb
    .from("comprobantes_compra")
    .update({ estado: "APROBADO" })
    .eq("id_comprobante", id_comprobante);

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  return NextResponse.json({ ok: true });
}

import { NextResponse, type NextRequest } from "next/server";
import { supabaseServer } from "@/lib/supabase/server";

// POST /api/mapeo/vincular
// body: { id_item: number, id_producto: number | null, guardar_alias: boolean, factor_unidad?: number }
// id_producto null => marcar CREAR_NUEVO
// factor_unidad: unidades del producto por cada unidad del comprobante (pack x12 → 12), para que el costo quede por unidad.
// Al vincular aplica el costo del comprobante (aplicar_costos_comprobantes: solo si sube o no había; si baja, queda
// en el aviso Productos → Costo bajó).
export async function POST(req: NextRequest) {
  const sb = await supabaseServer();
  const { data: { user } } = await sb.auth.getUser();
  if (!user) return NextResponse.json({ error: "Sin sesión" }, { status: 401 });

  const { data: perfil } = await sb.from("perfiles").select("rol").eq("id", user.id).single();
  if (perfil?.rol !== "administrador") return NextResponse.json({ error: "Sin permisos" }, { status: 403 });

  const body = await req.json().catch(() => ({})) as {
    id_item?: number;
    id_producto?: number | null;
    guardar_alias?: boolean;
    factor_unidad?: number;
  };
  const { id_item, id_producto, guardar_alias } = body;
  const factor = Number(body.factor_unidad);
  if (!id_item) return NextResponse.json({ error: "id_item requerido" }, { status: 400 });

  // Obtener el ítem para saber descripcion y proveedor
  const { data: item } = await sb
    .from("items_compra")
    .select("descripcion_original, id_comprobante")
    .eq("id_item", id_item)
    .single();

  if (!item) return NextResponse.json({ error: "Ítem no encontrado" }, { status: 404 });

  if (id_producto === null || id_producto === undefined) {
    // Marcar como CREAR_NUEVO
    const { error } = await sb
      .from("items_compra")
      .update({ estado_coincidencia: "CREAR_NUEVO", id_producto: null })
      .eq("id_item", id_item);
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json({ ok: true, accion: "CREAR_NUEVO" });
  }

  // Obtener proveedor del comprobante (necesario para alias y propagación)
  const { data: comp } = await sb
    .from("comprobantes_compra")
    .select("id_proveedor")
    .eq("id_comprobante", item.id_comprobante)
    .single();

  // Vincular el ítem individual
  const { error: errUpdate } = await sb
    .from("items_compra")
    .update({ id_producto, estado_coincidencia: "MANUAL", ...(factor > 0 ? { factor_unidad: factor } : {}) })
    .eq("id_item", id_item);
  if (errUpdate) return NextResponse.json({ error: errUpdate.message }, { status: 500 });

  let propagados = 0;

  if (guardar_alias && item.descripcion_original && comp?.id_proveedor) {
    // Upsert alias
    await sb.from("alias_producto_proveedor").upsert(
      {
        id_proveedor: comp.id_proveedor,
        descripcion_original: item.descripcion_original,
        id_producto,
        usuario_responsable: user.email,
      },
      { onConflict: "id_proveedor,descripcion_original" }
    );

    // Propagar a todos los ítems duplicados sin vincular del mismo proveedor+descripción
    const { data: propagacion } = await sb.rpc("vincular_duplicados", {
      p_id_proveedor: comp.id_proveedor,
      p_descripcion: item.descripcion_original,
      p_id_producto: id_producto,
      p_excluir_item: id_item,
    });
    propagados = propagacion ?? 0;
  }

  // Ítems "para crear" con la misma descripción del mismo proveedor: vincular_duplicados excluye CREAR_NUEVO.
  if (comp?.id_proveedor && item.descripcion_original) {
    const { data: iguales } = await sb.from("items_compra").select("id_item, comprobantes_compra!inner(id_proveedor)")
      .eq("comprobantes_compra.id_proveedor", comp.id_proveedor).eq("descripcion_original", item.descripcion_original)
      .is("id_producto", null).eq("estado_coincidencia", "CREAR_NUEVO").neq("id_item", id_item);
    const ids = (iguales ?? []).map((x) => x.id_item);
    if (ids.length) {
      const { error } = await sb.from("items_compra")
        .update({ id_producto, estado_coincidencia: "MANUAL", ...(factor > 0 ? { factor_unidad: factor } : {}) })
        .in("id_item", ids);
      if (!error) propagados += ids.length;
    }
  }

  const costos = await sb.rpc("aplicar_costos_comprobantes", { p_productos: [id_producto] });

  return NextResponse.json({ ok: true, accion: "MANUAL", propagados, costos_actualizados: costos.data ?? 0 });
}

