import { createClient } from '@supabase/supabase-js';
import { NextRequest, NextResponse } from 'next/server';
import { usuarioActual } from '@/lib/supabase/server';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

// GET: comprobante completo con ítems, nombre de producto y costo actual
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user, rol } = await usuarioActual();
    if (!user) return NextResponse.json({ error: 'No autenticado' }, { status: 401 });
    if (rol !== 'administrador') return NextResponse.json({ error: 'No autorizado' }, { status: 403 });

    const { id } = await params;
    const idComp = parseInt(id);
    if (!idComp) return NextResponse.json({ error: 'Comprobante inválido' }, { status: 400 });

    const [comp, items] = await Promise.all([
      supabase
        .from('comprobantes_compra')
        .select('id_comprobante,id_proveedor,tipo_comprobante,numero_comprobante,fecha_comprobante,subtotal,total_iva,total_percepciones,total_comprobante,estado,imputa_cta_cte,imputa_stock,nota_revision')
        .eq('id_comprobante', idComp)
        .single(),
      supabase
        .from('items_compra')
        .select('id_item,id_producto,codigo_proveedor,descripcion_original,cantidad,precio_unitario,descuento_pct,importe_total,estado_coincidencia,factor_unidad,accion')
        .eq('id_comprobante', idComp)
        .order('id_item'),
    ]);

    if (comp.error?.code === 'PGRST116' || (!comp.error && !comp.data)) {
      return NextResponse.json({ error: 'Comprobante no encontrado' }, { status: 404 });
    }
    if (comp.error) throw comp.error;
    if (items.error) throw items.error;

    // Traer nombre y costo actual de los productos vinculados
    const productIds = [...new Set((items.data ?? []).filter(i => i.id_producto).map(i => i.id_producto as number))];
    const productosMap: Record<number, { nombre: string; costo_actual: number | null }> = {};

    if (productIds.length > 0) {
      const [prodRes, precRes] = await Promise.all([
        supabase.from('productos').select('id_producto,nombre').in('id_producto', productIds),
        supabase.from('precios').select('id_producto,costo_unitario').in('id_producto', productIds),
      ]);
      const precMap = new Map((precRes.data ?? []).map(p => [p.id_producto, Number(p.costo_unitario)]));
      for (const p of prodRes.data ?? []) {
        productosMap[p.id_producto] = { nombre: p.nombre, costo_actual: precMap.get(p.id_producto) ?? null };
      }
    }

    const itemsEnriquecidos = (items.data ?? []).map(item => ({
      ...item,
      nombre_producto: item.id_producto ? (productosMap[item.id_producto]?.nombre ?? null) : null,
      costo_actual: item.id_producto ? (productosMap[item.id_producto]?.costo_actual ?? null) : null,
    }));

    return NextResponse.json({ ...comp.data, items: itemsEnriquecidos });
  } catch (error) {
    console.error('Error obteniendo comprobante:', error);
    return NextResponse.json({ error: 'Error al obtener comprobante' }, { status: 500 });
  }
}

// PUT: editar campos del comprobante (imputa_cta_cte, fechas, totales, estado)
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user, rol } = await usuarioActual();
    if (!user) return NextResponse.json({ error: 'No autenticado' }, { status: 401 });
    if (rol !== 'administrador') return NextResponse.json({ error: 'No autorizado' }, { status: 403 });

    const { id } = await params;
    const idComp = parseInt(id);
    if (!idComp) return NextResponse.json({ error: 'Comprobante inválido' }, { status: 400 });

    const body = await request.json();
    const upd: Record<string, unknown> = {};
    const campos = ['fecha_comprobante','tipo_comprobante','numero_comprobante','subtotal','total_iva','total_percepciones','total_comprobante','estado','nota_revision'] as const;
    for (const c of campos) if (body[c] !== undefined) upd[c] = body[c];

    const corrige = body.imputa_cta_cte !== undefined || body.imputa_stock !== undefined;
    if (Object.keys(upd).length === 0 && !corrige) return NextResponse.json({ error: 'Nada para guardar' }, { status: 400 });

    // Flags actuales: 404 si el comprobante no existe (antes de cualquier validación o escritura).
    const { data: actual, error: errActual } = await supabase
      .from('comprobantes_compra')
      .select('imputa_cta_cte,imputa_stock')
      .eq('id_comprobante', idComp)
      .maybeSingle();
    if (errActual) throw errActual;
    if (!actual) return NextResponse.json({ error: 'Comprobante no encontrado' }, { status: 404 });

    // Aprobar con este endpoint aplica el mismo control que /api/revision/aprobar: no se aprueba con ítems sin vincular.
    // Se valida ANTES de la RPC para no dejar cuenta corriente/stock aplicados si la aprobación se rechaza.
    if (upd.estado === 'APROBADO') {
      const { data: sinVincular, error: errCheck } = await supabase
        .from('items_compra')
        .select('id_item')
        .eq('id_comprobante', idComp)
        .is('id_producto', null)
        .not('estado_coincidencia', 'in', '("CREAR_NUEVO","IGNORAR","DESCARTADO")')
        .limit(1);
      if (errCheck) throw errCheck;
      if (sinVincular && sinVincular.length > 0) {
        return NextResponse.json({ error: 'El comprobante todavía tiene ítems sin vincular' }, { status: 422 });
      }
    }

    // Corrección de impacto + campos en UNA transacción (actualizar_comprobante): si algo falla, no queda nada aplicado.
    const { data: corr, error: errRpc } = await supabase.rpc('actualizar_comprobante', {
      p_id: idComp,
      p_upd: upd,
      p_corrige: corrige,
      p_cta: body.imputa_cta_cte ?? actual.imputa_cta_cte,
      p_stock: body.imputa_stock ?? actual.imputa_stock,
      p_usuario: user.email ?? user.id,
      p_motivo: typeof body.motivo === 'string' ? body.motivo : null,
    });
    if (errRpc) {
      // 23505: número duplicado para el proveedor. P0001: error de negocio levantado por la base (mensaje para el admin).
      if (errRpc.code === '23505') {
        return NextResponse.json({ error: 'Ya existe un comprobante con ese número para este proveedor' }, { status: 409 });
      }
      if (errRpc.code === 'P0001') {
        const status = /inexistente/i.test(errRpc.message) ? 404 : 422;
        return NextResponse.json({ error: errRpc.message }, { status });
      }
      throw errRpc;
    }

    const { data, error } = await supabase
      .from('comprobantes_compra')
      .select('id_comprobante,tipo_comprobante,numero_comprobante,fecha_comprobante,total_comprobante,estado,imputa_cta_cte,imputa_stock')
      .eq('id_comprobante', idComp)
      .single();
    if (error) throw error;
    if (!data) return NextResponse.json({ error: 'Comprobante no encontrado' }, { status: 404 });

    // Conteos de la corrección (solo si se corrigió impacto): para que la UI pueda avisar qué se aplicó o revirtió.
    const c = (corr ?? {}) as Record<string, number>;
    const conteos = corrige
      ? {
          aplicaciones_cta: c.aplicaciones_cta ?? 0,
          reversas_cta: c.reversas_cta ?? 0,
          aplicaciones_stock: c.aplicaciones_stock ?? 0,
          reversas_stock: c.reversas_stock ?? 0,
        }
      : {};
    return NextResponse.json({ ...data, ...conteos });
  } catch (error) {
    console.error('Error actualizando comprobante:', error);
    return NextResponse.json({ error: 'Error al actualizar comprobante' }, { status: 500 });
  }
}

// DELETE: borra el comprobante, sus ítems y su movimiento de cuenta corriente (ajusta el saldo). Función borrar_comprobante.
export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user, rol } = await usuarioActual();
    if (!user) return NextResponse.json({ error: 'No autenticado' }, { status: 401 });
    if (rol !== 'administrador') return NextResponse.json({ error: 'No autorizado' }, { status: 403 });

    const { id } = await params;
    const idComp = parseInt(id);
    if (!idComp) return NextResponse.json({ error: 'Comprobante inválido' }, { status: 400 });

    const { data, error } = await supabase.rpc('borrar_comprobante', { p_id: idComp, p_usuario: user.email ?? user.id });
    if (error) return NextResponse.json({ error: error.message }, { status: 400 });
    return NextResponse.json(data);
  } catch (error) {
    console.error('Error borrando comprobante:', error);
    return NextResponse.json({ error: 'Error al borrar comprobante' }, { status: 500 });
  }
}

