export const aMin = (hhmm: string) => { const [h, m] = hhmm.split(":").map(Number); return h * 60 + (m || 0); };
export const aHHMM = (min: number) => `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;

export type Slot = { hora: string; fin: string };

export function calcularSlots({ desde, hasta, duracion, extra, turnosDelDia, ahoraMin, esHoy }: {...}): Slot[]
```

Given franja desde/hasta, duracion, extra buffer, existing turnos (hora/fin), skip past slots for today.

```ts
export function calcularSlots(
  desde: string, hasta: string, duracion: number, extra: number,
  ocupados: { hora: string; fin: string }[],
  ahoraMin?: number
): Slot[] {
  const slots: Slot[] = [];
  const ini = aMin(desde), fin = aMin(hasta);
  const paso = duracion + extra;
  for (let t = ini; t + duracion <= fin; t += paso) {
    const tFin = t + duracion;
    if (ahoraMin !== undefined && t < ahoraMin) continue;
    const choca = ocupados.some(o => t < aMin(o.fin) && tFin > aMin(o.hora));
    if (choca) continue;
    slots.push({ hora: aHHMM(t), fin: aHHMM(tFin) });
  }
  return slots;
}
```

