import { sb } from "./supabase";

export type ConfigMap = Record<string, string>;

const defaults: ConfigMap = {
  telefono_wa: "5491100000000",
  email_admin: "",
  alias_cbu: "",
  nombre_negocio: "Maquillaje Profesional",
  instagram: "",
  texto_hero: "",
  texto_sobre_mi: "",
  hold_minutos: "60",
  horas_vence_transferencia: "12",
  min_extra: "10",
};

/** Configuración clave/valor leída de la base, con valores por defecto. */
export async function getConfig(): Promise<ConfigMap> {
  const { data, error } = await sb().from("config").select("clave,valor");
  if (error) throw new Error(`CONFIG_ERROR: ${error.message}`);
  const map = { ...defaults };
  for (const { clave, valor } of data ?? []) {
    if (valor != null && valor !== "") map[clave] = valor;
  }
  return map;
}

export const numero = (n: string | number | null | undefined) => Number(n ?? 0);

/** "$ 15.000" con separador de miles argentino. */
export const pesos = (n: string | number | null | undefined) =>
  `$ ${numero(n).toLocaleString("es-AR")}`;

/** Herramientas de horarios: todo se calcula en minutos desde "HH:MM". */

export type Slot = { hora: string; fin: string };
export type Franja = { desde: string; hasta: string };
export type Ocupado = { hora: string; fin: string };

export const aMin = (hhmm: string): number => {
  const [h, m] = hhmm.split(":").map(Number);
  return h * 60 + (m || 0);
};

export const aHHMM = (min: number): string =>
  `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;

/** Fecha local (no UTC) formateada como YYYY-MM-DD. */
export const aISO = (d: Date): string => {
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
};

export const hoyISO = (): string => aISO(new Date());

/**
 * Turnos posibles para una franja: arranca en `desde` y avanza de a
 * (duracion + extra) minutos, sin pasar de `hasta`, sin superponerse con
 * turnos ya tomados y, si es hoy, sin ofrecer horarios que ya pasaron.
 */
export function calcularSlots(
  franja: Franja,
  duracionMin: number,
  extraMin: number,
  ocupados: Ocupado[],
  ahoraMin?: number,
): Slot[] {
  const slots: Slot[] = [];
  const paso = duracionMin + extraMin;
  const ini = aMin(franja.desde);
  const fin = aMin(franja.hasta);
  for (let t = ini; t + duracionMin <= fin; t += paso) {
    if (ahoraMin !== undefined && t < ahoraMin) continue;
    const tFin = t + duracionMin;
    const choca = ocupados.some((o) => t < aMin(o.fin) && tFin > aMin(o.hora));
    if (choca) continue;
    slots.push({ hora: aHHMM(t), fin: aHHMM(tFin) });
  }
  return slots;
}

/** Cuántos turnos entran como máximo en una franja (para los puntos del calendario). */
export function capacidadFranja(franja: Franja, duracionMin: number, extraMin: number): number {
  const paso = duracionMin + extraMin;
  return Math.max(0, Math.floor((aMin(franja.hasta) - aMin(franja.desde)) / paso));
}

import { sb } from "./supabase";

/**
 * Registra un aviso: lo manda por mail si hay Resend configurado y siempre
 * deja una copia en la tabla `avisos` (visible en Panel → Avisos), así el
 * flujo nunca se corta aunque el mail no esté configurado todavía.
 */
export async function avisar(
  tipo: "RESERVA_RECIBIDA" | "TURNO_CONFIRMADO" | "TURNO_CANCELADO",
  para: string | null,
  asunto: string,
  cuerpo: string,
): Promise<void> {
  const key = process.env.RESEND_API_KEY;
  let estado: "PENDIENTE" | "ENVIADO" | "ERROR" = "PENDIENTE";
  let detalle: string | null = null;

  if (key && para) {
    try {
      const r = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          from: process.env.RESEND_FROM || "Reservas <onboarding@resend.dev>",
          to: [para],
          subject: asunto,
          text: cuerpo,
        }),
      });
      estado = r.ok ? "ENVIADO" : "ERROR";
      if (!r.ok) detalle = (await r.text()).slice(0, 500);
    } catch (e) {
      estado = "ERROR";
      detalle = String(e).slice(0, 500);
    }
  }

  try {
    await sb().from("avisos").insert({ tipo, para, asunto, cuerpo, estado, detalle });
  } catch {
    // Si falla el registro del aviso no debe cortar la reserva.
  }
}

import { cookies } from "next/headers";
import { createHmac } from "crypto";

/** Panel de administración: acceso con contraseña (env ADMIN_PASSWORD). */
const password = () => process.env.ADMIN_PASSWORD || "maquillaje2026";

/** Token derivado de la contraseña: si la cambian, las sesiones viejas mueren. */
const token = () =>
  createHmac("sha256", password()).update("makup-admin").digest("hex").slice(0, 32);

export const COOKIE = "makup_admin";

export async function esAdmin(): Promise<boolean> {
  const c = await cookies();
  return c.get(COOKIE)?.value === token();
}

export const valorCookie = token;

import { sb } from "./supabase";

/**
 * Pasa los turnos PENDIENTES cuya seña venció a VENCIDO.
 * Se llama en cada lectura de disponibilidad y del panel, así el horario
 * se libera solo (sin cron).
 */
export async function liberarVencidos(): Promise<void> {
  await sb()
    .from("turnos")
    .update({ estado: "VENCIDO" })
    .eq("estado", "PENDIENTE")
    .lt("vence_at", new Date().toISOString());
}

