But reserva/[id] has no cancel button (public cancel) — mentioned earlier; add small "Cancelar reserva" for PENDIENTE via POST /api/turnos/cancelar? That requires client. Skip? But users should be able to cancel a pending booking. I said earlier route /api/turnos/cancelar public limited: only PENDIENTE. But a malicious person could cancel others' reservations knowing id. Low risk, but better: cancel only allowed via admin panel. Keep: user cancels via WhatsApp. Remove /api/turnos/cancelar. Admin panel can cancel.

DISPONIBILIDAD route:

```ts
import { NextRequest, NextResponse } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";
import { calcularSlots, capacidadFranja, aMin, aISO } from "@/lib/agenda";
import { liberarVencidos } from "@/lib/turnos";

const activos = ["PENDIENTE", "CONFIRMADO"] as const;

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = req.nextUrl;
    const duracion = Math.max(15, Number(searchParams.get("duracion")) || 60);
    const cfg = await getConfig();
    const extra = Math.max(0, Number(cfg.min_extra) || 0);

    // ¿? mes o fecha
    const mes = searchParams.get("mes");
    const fecha = searchParams.get("fecha");
    await liberarVencidos();

    const sbc = sb();
    const { data: agenda } = await sbc.from("agenda").select("dia,desde,hasta").eq("activo", true);
    const franjaDe = (d: number) => (agenda ?? []).find(f => f.dia === d) ?? null;

    if (mes) {
      // fechas con lugares libres
      const [a, m] = mes.split("-").map(Number);
      const desdeISO = `${mes}-01`;
      const dInicio = new Date(a, m - 1, 1);
      const dFin = new Date(a, m, 0);
      const hastaISO = aISO(dFin);
      const { data: turnos } = await sbc.from("turnos").select("fecha").gte("fecha", desdeISO).lte("fecha", hastaISO).in("estado", [...activos]);
      const { data: bloqueos } = await sbc.from("bloqueos").select("fecha").gte("fecha", desdeISO).lte("fecha", hastaISO);
      const ocup = new Map<string, number>(); for (const t of turnos ?? []) ocup.set(t.fecha, (ocup.get(t.fecha) ?? 0) + 1);
      const blos = new Set((bloqueos ?? []).map(b => b.fecha));
      const fechas: Record<string, number> = {};
      for (let d = 1; d <= dFin.getDate(); d++) {
        const dObj = new Date(a, m - 1, d);
        const iso = aISO(dObj);
        if (iso < aISO(new Date())) continue;
        if (blos.has(iso)) continue;
        const franja = franjaDe(dObj.getDay());
        if (!franja) continue;
        const libres = Math.max(0, capacidadFranja(franja, duracion, extra) - (ocup.get(iso) ?? 0));
        if (libres > 0) fechas[iso] = libres;
      }
      return NextResponse.json({ fechas });
    }

    if (fecha) {
      const d = new Date(fecha + "T12:00:00");
      const franja = franjaDe(d.getDay());
      if (!franja) return NextResponse.json({ slots: [] });
      const { data: turnos } = await sbc.from("turnos").select("hora,fin").eq("fecha", fecha).in("estado", [...activos]);
      const hoy = aISO(new Date());
      const ahoraMin = fecha === hoy ? new Date().getHours() * 60 + new Date().getMinutes() : undefined;
      const slots = calcularSlots(franja, duracion, extra, turnos ?? [], ahoraMin);
      return NextResponse.json({ slots });
    }

    return NextResponse.json({ error: "Falta mes o fecha." }, { status: 400 });
  } catch (e) {
    return NextResponse.json({ error: detailed(e) }, { status: 500 });
  }
}
