import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";
import { liberarVencidos } from "@/lib/turnos";
import { calcularSlots, capacidadFranja, aISO } from "@/lib/agenda";
import type { Franja } from "@/lib/agenda";

const ACTIVOS = ["PENDIENTE", "CONFIRMADO"] as const;

/** Franjas de agenda por día de la semana (0 = domingo). */
async function agendaPorDia() {
  const { data } = await sb().from("agenda").select("dia,desde,hasta").eq("activo", true);
  const mapa = new Map<number, Franja>();
  for (const f of data ?? []) mapa.set(f.dia, f);
  return mapa;
}

/**
 * GET /api/disponibilidad?mes=2026-11&duracion=60  → { fechas: { "2026-11-12": 5 } }
 * GET /api/disponibilidad?fecha=2026-11-12&duracion=60 → { slots: [{ hora, fin }] }
 */
export async function GET(req: NextRequest) {
  try {
    const { searchParams } = req.nextUrl;
    const duracion = Math.max(15, Number(searchParams.get("duracion")) || 60);
    const cfg = await getConfig();
    const extra = Math.max(0, Number(cfg.min_extra) || 0);
    await liberarVencidos();

    const franjas = await agendaPorDia();
    const mes = searchParams.get("mes");
    const fecha = searchParams.get("fecha");

    // ── Resumen del mes (puntos del calendario) ──
    if (mes) {
      if (!/^\d{4}-\d{2}$/.test(mes)) {
        return NextResponse.json({ error: "Mes inválido." }, { status: 400 });
      }
      const [a, m] = mes.split("-").map(Number);
      const primero = new Date(a, m - 1, 1);
      const ultimo = new Date(a, m, 0);
      const desde = aISO(primero);
      const hasta = aISO(ultimo);

      const [turnosRes, bloqueosRes] = await Promise.all([
        sb().from("turnos").select("fecha").gte("fecha", desde).lte("fecha", hasta).in("estado", [...ACTIVOS]),
        sb().from("bloqueos").select("fecha").gte("fecha", desde).lte("fecha", hasta),
      ]);
      const ocupados = new Map<string, number>();
      for (const t of turnosRes.data ?? []) {
        ocupados.set(t.fecha, (ocupados.get(t.fecha) ?? 0) + 1);
      }
      const bloqueados = new Set((bloqueosRes.data ?? []).map((b) => b.fecha));

      const fechas: Record<string, number> = {};
      const hoy = aISO(new Date());
      for (let d = 1; d <= ultimo.getDate(); d++) {
        const dObj = new Date(a, m - 1, d);
        const iso = aISO(dObj);
        if (iso < hoy || bloqueados.has(iso) || !franjas.has(dObj.getDay())) continue;
        const libres = Math.max(
          0,
          capacidadFranja(franjas.get(dObj.getDay())!, duracion, extra) - (ocupados.get(iso) ?? 0),
        );
        if (libres > 0) fechas[iso] = libres;
      }
      return NextResponse.json({ fechas });
    }

    // ── Horarios exactos de un día ──
    if (fecha) {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
        return NextResponse.json({ error: "Fecha inválida." }, { status: 400 });
      }
      const franja = franjas.get(new Date(`${fecha}T12:00:00`).getDay());
      if (!franja) return NextResponse.json({ slots: [] });

      const { data: turnos } = await sb()
        .from("turnos")
        .select("hora,fin")
        .eq("fecha", fecha)
        .in("estado", [...ACTIVOS]);

      const ahora = new Date();
      const ahoraMin = fecha === aISO(ahora) ? ahoraminutos(ahora) : undefined;
      return NextResponse.json({
        slots: calcularSlots(franja, duracion, extra, turnos ?? [], ahoraMin),
      });
    }

    return NextResponse.json({ error: "Pasá mes o fecha." }, { status: 400 });
  } catch (e) {
    return NextResponse.json({ error: mensaje(e) }, { status: 500 });
  }
}

const ahoraminutos = (d: Date) => d.getHours() * 60 + d.getMinutes();

const mensaje = (e: unknown) => (e instanceof Error ? e.message : "Error interno.");

import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";
import { liberarVencidos } from "@/lib/turnos";
import { avisar } from "@/lib/mail";
import { calcularSlots, aISO, pesos } from "@/lib/agenda-utiles";
import type { Servicio } from "@/types";

type Cuerpo = {
  id_servicio?: number;
  fecha?: string;
  hora?: string;
  nombre?: string;
  telefono?: string;
  instagram?: string;
  notas?: string;
};

/** POST /api/turnos: crea la reserva y bloquea el horario ( estado PENDIENTE ). */
export async function POST(req: NextRequest) {
  try {
    const b = (await req.json().catch(() => ({}))) as Cuerpo;
    const nombre = (b.nombre ?? "").trim();
    const telefono = (b.telefono ?? "").trim();
    const fecha = (b.fecha ?? "").trim();
    const hora = (b.hora ?? "").trim();

    if (!nombre || !telefono || !fecha || !hora) {
      return NextResponse.json({ error: "Falta completar datos de la reserva." }, { status: 400 });
    }
    if (nombre.length > 120 || telefono.length > 40) {
      return NextResponse.json({ error: "Datos demasiado largos." }, { status: 400 });
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:\d{2}$/.test(hora)) {
      return NextResponse.json({ error: "Fecha u horario inválido." }, { status: 400 });
    }

    const cfg = await getConfig();
    const extra = Math.max(0, Number(cfg.min_extra) || 0);
    await liberarVencidos();

    if (fecha < aISO(new Date())) {
      return NextResponse.json({ error: "Elegí una fecha futura." }, { status: 400 });
    }

    // Servicio (siempre activo): el precio y la seña salen SIEMPRE de la base.
    const { data: serv } = await sb()
      .from("servicios")
      .select("*")
      .eq("id", Number(b.id_servicio))
      .eq("activo", true)
      .maybeSingle();
    if (!serv) {
      return NextResponse.json({ error: "Ese servicio ya no está disponible." }, { status: 404 });
    }
    const servicio = serv as Servicio;

    // El horario tiene que seguir libre: lo recalculamos acá (no confiamos en el navegador).
    const diaSemana = new Date(`${fecha}T12:00:00`).getDay();
    const { data: franja } = await sb()
      .from("agenda")
      .select("desde,hasta")
      .eq("dia", diaSemana)
      .eq("activo", true)
      .maybeSingle();
    if (!franja) {
      return NextResponse.json({ error: "Ese día no atiendo. Elegí otro." }, { status: 400 });
    }

    const { data: ocupados } = await sb()
      .from("turnos")
      .select("hora,fin")
      .eq("fecha", fecha)
      .in("estado", ["PENDIENTE", "CONFIRMADO"]);

    const ahora = new Date();
    const ahoraMin = fecha === aISO(ahora) ? ahora.getHours() * 60 + ahora.getMinutes() : undefined;
    const slots = calcularSlots(franja, servicio.duracion_min, extra, ocupados ?? [], ahoraMin);
    const elegido = slots.find((s) => s.hora === hora);
    if (!elegido) {
      return NextResponse.json({ error: "Ese horario ya no está disponible. Elegí otro." }, { status: 409 });
    }

    // Crear el turno con el bloqueo de tiempo (hold).
    const holdMin = Math.max(5, Number(cfg.hold_minutos) || 60);
    const venceAt = new Date(Date.now() + holdMin * 60_000).toISOString();
    const { data: creado, error: errInsert } = await sb()
      .from("turnos")
      .insert({
        id_servicio: servicio.id,
        fecha,
        hora: elegido.hora,
        fin: elegido.fin,
        nombre,
        telefono,
        instagram: (b.instagram ?? "").trim() || null,
        notas: (b.notas ?? "").trim() || null,
        estado: "PENDIENTE",
        sena_monto: servicio.sena_monto,
        vence_at: venceAt,
      })
      .select("id")
      .single();
    if (errInsert || !creado) {
      // Doble clic / carrera: probablemente ya existe.
      return NextResponse.json(
        { error: "No pudimosGuardar el turno, probá otra vez." },
        { status: 409 },
      );
    }

    const emailAdmin = cfg.email_admin;
    await avisar(
      "RESERVA_RECIBIDA",
      emailAdmin || null,
      `Nueva reserva #${creado.id}: ${servicio.nombre} — ${fecha} ${hora}`,
      [
        `Reserva #${creado.id}`,
        `Servicio: ${servicio.nombre} (${servicio.duracion_min} min)`,
        `Fecha y hora: ${fecha} de ${elegido.hora} a ${elegido.fin}`,
        `Clienta: ${nombre} · Tel: ${telefono}${b.instagram ? ` · IG: ${b.instagram}` : ""}`,
        `Total: ${pesos(servicio.precio)} · Seña: ${pesos(servicio.sena_monto)}`,
        b.notas ? `Notas: ${b.notas}` : "",
      ].filter(Boolean).join("\n"),
    );

    return NextResponse.json({ id: creado.id, fin: elegido.fin });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "Error interno." },
      { status: 500 },
    );
  }
}

