import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";

/**
 * POST /api/turnos/medio { id, medio }
 * Registra el método de pago elegido y recalcular el vencimiento:
 * - TRANSFERENCIA: más tiempo (horas_vence_transferencia) porque llega manualmente.
 * - MERCADOPAGO: se mantiene el bloqueo original (se confirma por webhook).
 */
export async function POST(req: NextRequest) {
  try {
    const { id, medio } = (await req.json().catch(() => ({}))) as { id?: number; medio?: string };
    if (!Number.isInteger(id) || (medio !== "TRANSFERENCIA" && medio !== "MERCADOPAGO")) {
      return NextResponse.json({ error: "Datos inválidos." }, { status: 400 });
    }

    const { data: turno } = await sb()
      .from("turnos")
      .select("id,estado")
      .eq("id", Number(id))
      .maybeSingle();
    if (!turno) return NextResponse.json({ error: "Reserva no encontrada." }, { status: 404 });
    if (turno.estado !== "PENDIENTE" || turno.metodo === "MERCADOPAGO") {
      return NextResponse.json({ ok: true });
    }

    const patch: Record<string, unknown> = { metodo: medio };
    if (medio === "TRANSFERENCIA") {
      const cfg = await getConfig();
      const horas = Math.max(1, Number(cfg.horas_vence_transferencia) || 12);
      patch.vence_at = new Date(Date.now() + horas * 3_600_000).toISOString();
    }

    const { error } = await sb().from("turnos").update(patch).eq("id", Number(id));
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
    return NextResponse.json({ ok: true });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "Error interno." },
      { status: 500 },
    );
  }
}

import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";

type TurnoPago = {
  id: number;
  estado: string;
  sena_monto: number;
  servicio: { nombre: string } | null;
};

/**
 * POST /api/pago/mercadopago { id_turno }
 * - Crea la preferencia de MP con el monto de la seña SIEMPRE sacado de la base.
 * - Con JSON devuelve { init_point } (lo usa el flujo de reserva).
 * - Con formulario (form POST desde /reserva) redirige directo al checkout.
 */
export async function POST(req: NextRequest) {
  const token = process.env.MP_ACCESS_TOKEN;
  const esJson = (req.headers.get("content-type") ?? "").includes("application/json");

  const responder = (status: number, error: string, initPoint?: string) => {
    if (esJson) {
      return initPoint
        ? NextResponse.json({ init_point: initPoint })
        : NextResponse.json({ error }, { status });
    }
    const destino = new URL(initPoint ?? `/reserva/${""}`, req.nextUrl.origin);
    return NextResponse.redirect(destino, { status: 303 });
  };

  if (!token) return responder(503, "Mercado Pago no está configurado todavía.");

  try {
    let idTurno = 0;
    if (esJson) {
      const j = (await req.json().catch(() => ({}))) as { id_turno?: number };
      idTurno = Number(j.id_turno);
    } else {
      const f = await req.formData();
      idTurno = Number(f.get("id_turno"));
    }
    if (!Number.isInteger(idTurno) || idTurno <= 0) {
      return responder(400, "Reserva inválida.", undefined);
    }

    const { data: t } = await sb()
      .from("turnos")
      .select("id,estado,sena_monto,servicio: id_servicio(nombre)")
      .eq("id", idTurno)
      .maybeSingle();
    const turno = t as TurnoPago | null;
    if (!turno) return responder(404, "Reserva no encontrada.", undefined);
    if (turno.estado !== "PENDIENTE") {
      return responder(409, "Esta reserva ya está gestionada.", undefined);
    }

    await sb().from("turnos").update({ metodo: "MERCADOPAGO" }).eq("id", idTurno);

    const site = req.nextUrl.origin;
    const r = await fetch("https://api.mercadopago.com/checkout/preferences", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        items: [
          {
            title: `Seña - ${turno.servicio?.nombre ?? "Maquillaje"} (Turno #${turno.id})`,
            quantity: 1,
            unit_price: Number(turno.sena_monto),
            currency_id: "ARS",
          },
        ],
        external_reference: String(turno.id),
        back_urls: {
          success: `${site}/reserva/${turno.id}`,
          pending: `${site}/reserva/${turno.id}`,
          failure: `${site}/reserva/${turno.id}`,
        },
        auto_return: "approved",
        notification_url: `${site}/api/pago/webhook`,
      }),
    });
    const j = (await r.json()) as { init_point?: string; message?: string };
    if (!r.ok || !j.init_point) {
      return responder(502, "No pudimos iniciar el pago con Mercado Pago.", undefined);
    }

    return responder(200, "", j.init_point);
  } catch (e) {
    return responder(500, e instanceof Error ? e.message : "Error interno.", undefined);
  }
}

import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";
import { avisar } from "@/lib/mail";
import { pesos } from "@/lib/config";

type MPNotificacion = { action?: string; data?: { id?: string | number } };

/**
 * Webhook de Mercado Pago: no tiene sesión de usuario, por eso todo el access
 * se hace con el cliente de servicio. Verificamos el pago contra la API de MP
 * (no confiamos en el cuerpo de la notificación) y confirmamos el turno.
 */
export async function POST(req: NextRequest) {
  try {
    const cuerpo = (await req.json().catch(() => ({}))) as MPNotificacion;
    if (cuerpo.action !== "payment.created" || !cuerpo.data?.id) {
      return NextResponse.json({ ok: true });
    }

    const token = process.env.MP_ACCESS_TOKEN;
    if (!token) return NextResponse.json({ error: "MP no configurado." }, { status: 500 });

    const r = await fetch(`https://api.mercadopago.com/v1/payments/${cuerpo.data.id}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!r.ok) return NextResponse.json({ ok: true }); // no frenamos al notificador
    const pago = (await r.json()) as {
      status?: string;
      transaction_amount?: number;
      external_reference?: string;
    };

    if (pago.status !== "approved") return NextResponse.json({ ok: true });
    const idTurno = Number(pago.external_reference);
    if (!Number.isInteger(idTurno) || idTurno <= 0) return NextResponse.json({ ok: true });

    const { data: turno } = await sb()
      .from("turnos")
      .select("id,estado,nombre,fecha,hora,sena_monto,servicio: id_servicio(nombre)")
      .eq("id", idTurno)
      .maybeSingle() as { data: {
        id: number; estado: string; nombre: string; fecha: string; hora: string;
        sena_monto: number; servicio: { nombre: string } | null;
      } | null };
    if (!turno || turno.estado !== "PENDIENTE") return NextResponse.json({ ok: true });

    const { error } = await sb()
      .from("turnos")
      .update({
        estado: "CONFIRMADO",
        metodo: "MERCADOPAGO",
        mp_payment_id: String(cuerpo.data.id),
        confirmado_at: new Date().toISOString(),
      })
      .eq("id", idTurno);
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });

    const cfg = await getConfig();
    await avisar(
      "TURNO_CONFIRMADO",
      cfg.email_admin || null,
      `Pago recibido: turno #${turno.id} CONFIRMADO`,
      [
        `Señá cobrada por Mercado Pago: ${pesos(pago.transaction_amount ?? turno.sena_monto)}`,
        `Turno #${turno.id}: ${turno.servicio?.nombre ?? ""} — ${turno.fecha} ${turno.hora}`,
        `Clienta: ${turno.nombre}`,
      ].join("\n"),
    );

    return NextResponse.json({ ok: true });
  } catch {
    // Igual respondemos 200: MP reintenta si hace falta.
    return NextResponse.json({ ok: true });
  }
}

