          <button type="button" className="btn btn-pri btn-block" disabled={!datosValidos || enviando} onClick={crearTurno}>
            {enviando ? "Reservando…" : "CONFIRMAR RESERVA"}
          </button>
        </>
      )}
    </div>
  );
}

