import { NextResponse, type NextRequest } from "next/server";
import { sb } from "@/lib/supabase";
import { getConfig } from "@/lib/config";
import { avisar } from "@/lib/mail";

/**
 * POST /api/turnos/cancelar { id, codigo }
 * Cancelación autogestionada: solo con el código de la reserva (SM-XXXX)
 * y solo si está PENDIENTE o CONFIRMADO.
 */
export async function POST(req: NextRequest) {
  try {
    const { id, codigo } = (await req.json().catch(() => ({}))) as { id?: number; codigo?: string };
    if (!Number.isInteger(id) || !codigo) {
      return NextResponse.json({ error: "Faltan los datos de la reserva." }, { status: 400 });
    }

    const { data: turno } = await sb()
      .from("turnos")
      .select("id,codigo,estado,nombre,fecha,hora,servicio: id_servicio(nombre)")
      .eq("id", Number(id))
      .maybeSingle() as { data: {
        id: number; codigo: string | null; estado: string; nombre: string;
        fecha: string; hora: string; servicio: { nombre: string } | null;
      } | null };

    if (!turno) return NextResponse.json({ error: "Reserva no encontrada." }, { status: 404 });
    if (turno.estado === "CANCELADO" || turno.estado === "VENCIDO") {
      return NextResponse.json({ error: "Esta reserva ya está cerrada." }, { status: 409 });
    }

    if ((turno.codigo ?? "").toUpperCase() !== String(codigo).trim().toUpperCase()) {
      return NextResponse.json({ error: "El código no corresponde a esta reserva." }, { status: 403 });
    }

    const { error } = await sb().from("turnos").update({ estado: "CANCELADO" }).eq("id", Number(id));
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });

    const cfg = await getConfig();
    await avisar(
      "TURNO_CANCELADO",
      cfg.email_admin || null,
      `Reserva ${turno.codigo ?? turno.id} cancelada por la clienta`,
      [
        `Turno #${turno.id}: ${turno.servicio?.nombre ?? ""} — ${turno.fecha} ${turno.hora}`,
        `Clienta: ${turno.nombre}`,
        "El horario queda libre.",
      ].join("\n"),
    );

    return NextResponse.json({ ok: true });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "Error interno." },
      { status: 500 },
    );
  }
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { sb, configurado } from "@/lib/supabase";

export const dynamic = "force-dynamic";

/** /mis-reservas: la clienta busca su reserva con el código (SM-1024). */
export default async function MisReservas({
  searchParams,
}: {
  searchParams: Promise<{ codigo?: string }>;
}) {
  if (!configurado) redirect("/");
  const { codigo } = await searchParams;
  const normalizado = (codigo ?? "").trim().toUpperCase().replace(/^SM[- ]?/, "");
  let error = "";

  if (normalizado) {
    const { data } = await sb()
      .from("turnos")
      .select("id")
      .eq("codigo", `SM-${normalizado}`)
      .maybeSingle();
    if (data) redirect(`/reserva/${data.id}`);
    error = "No encontré una reserva con ese código. Revisalo y probá otra vez.";
  }

  return (
    <main className="bk fade-in">
      <Link href="/" className="backlink">← Volver al inicio</Link>
      <h2 className="serif mt-6">Mis reservas</h2>
      <p className="sub">Poné el código que te dio la página al confirmar la reserva (ej: SM-1024).</p>

      <div className="card p-5">
        <form method="get">
          <label className="lbl" htmlFor="rv-codigo">CÓDIGO DE RESERVA</label>
          <input id="rv-codigo" name="codigo" className="input" placeholder="SM-1024" defaultValue={codigo ?? ""} />
          <button type="submit" className="btn btn-pri btn-block" style={{ marginTop: "1rem" }}>VER MI RESERVA →</button>
        </form>
        {error && <p className="status-err mt-4">{error}</p>}
      </div>
    </main>
  );
}

"use client";

import { useState } from "react";

/** Cancelación autogestionada de la clienta con su código. */
export default function CancelarReserva({ idTurno }: { idTurno: number }) {
  const [abierto, setAbierto] = useState(false);
  const [codigo, setCodigo] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);

  const cancelar = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setEnviando(true);
    try {
      const r = await fetch("/api/turnos/cancelar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: idTurno, codigo }),
      });
      const j = (await r.json().catch(() => ({}))) as { error?: string };
      if (r.ok) {
        window.location.reload();
        return;
      }
      setError(j.error ?? "No pudimos cancelar la reserva.");
    } finally {
      setEnviando(false);
    }
  };

  if (!abierto) {
    return (
      <button type="button" className="link-danger" onClick={() => setAbierto(true)}>
        ✕ CANCELAR RESERVA
      </button>
    );
  }

  return (
    <form onSubmit={cancelar} className="w-full" style={{ marginTop: "0.75rem" }}>
      <label className="lbl" htmlFor="cn-codigo">CONFIRMÁ CON TU CÓDIGO (SM-1024)</label>
      <input
        id="cn-codigo"
        className="input"
        value={codigo}
        onChange={(e) => setCodigo(e.target.value)}
        placeholder="SM-1024"
        autoFocus
      />
      {error && <p className="status-err mt-3">{error}</p>}
      <div className="res-actions">
        <button type="submit" disabled={enviando || !codigo} className="link-danger">
          {enviando ? "Cancelando…" : "✕ CONFIRMAR CANCELACIÓN"}
        </button>
        <button type="button" className="muted underline" onClick={() => setAbierto(false)}>
          no, volver
        </button>
      </div>
    </form>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { sb, configurado } from "@/lib/supabase";
import { getConfig, pesos } from "@/lib/config";
import CancelarReserva from "@/components/cancelar-reserva";
import { IconoWa } from "@/components/iconos";

export const dynamic = "force-dynamic";

type Turno = {
  id: number;
  codigo: string | null;
  fecha: string;
  hora: string;
  fin: string;
  nombre: string;
  estado: string;
  sena_monto: number;
  metodo: string | null;
  servicio: { nombre: string; duracion_min: number; precio: number } | null;
};

const ROTULO: Record<string, { texto: string; badge: string; detalle: string; cancelable: boolean }> = {
  PENDIENTE: {
    texto: "PENDIENTE DE SEÑA",
    badge: "wt",
    detalle: "Tu horario quedó bloqueado. Se confirma en cuanto llegue la seña.",
    cancelable: true,
  },
  CONFIRMADO: {
    texto: "CONFIRMADA",
    badge: "ok",
    detalle: "¡Listo! Te esperamos ese día y horario.",
    cancelable: true,
  },
  VENCIDO: {
    texto: "CANCELADA · VENCIDA",
    badge: "no",
    detalle: "El horario se liberó porque no llegó la seña a tiempo. Podés reservar de nuevo.",
    cancelable: false,
  },
  CANCELADO: {
    texto: "CANCELADA",
    badge: "no",
    detalle: "Esta reserva quedó cancelada.",
    cancelable: false,
  },
};

export default async function PaginaReserva({ params }: { params: Promise<{ id: string }> }) {
  if (!configurado) notFound();
  const { id } = await params;
  const idNum = Number(id);
  if (!Number.isInteger(idNum) || idNum <= 0) notFound();

  const [cfg, turnoRes] = await Promise.all([
    getConfig(),
    sb()
      .from("turnos")
      .select("id,codigo,fecha,hora,fin,nombre,estado,sena_monto,metodo,servicio: id_servicio(nombre,duracion_min,precio)")
      .eq("id", idNum)
      .maybeSingle(),
  ]);
  const turno = turnoRes.data as Turno | null;
  if (!turno) notFound();

  const info = ROTULO[turno.estado] ?? ROTULO.PENDIENTE;
  const wa = (cfg.telefono_wa || "").replace(/\D/g, "");
  const waMsg = encodeURIComponent(
    `¡Hola ${cfg.marca}! Consulto por mi reserva ${turno.codigo ?? turno.id} de ${turno.servicio?.nombre ?? "maquillaje"} (${turno.fecha} ${turno.hora}).`,
  );
  const formatFecha = (iso: string) => {
    const [a, m, d] = iso.split("-").map(Number);
    return `${a}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  };

  return (
    <main className="wrap pt-8">
      <Link href="/" className="backlink">← Inicio</Link>

      <div className="res-card card fade-in mt-6" style={{ marginBottom: "6rem" }}>
        <div className="res-top">
          <div>
            <p className="font-semibold" style={{ color: "var(--fg)" }}>{turno.servicio?.nombre}</p>
            <p className="muted mt-1 capitalize">{turno.fecha} — {turno.hora}</p>
          </div>
          <span className={`badge ${info.badge}`}>{info.texto}</span>
        </div>

        <div className="res-meta">
          <span><b style={{ color: "var(--fg-suave)" }}>{turno.nombre}</b> · {turno.metodo === "TRANSFERENCIA" ? "transferencia" : turno.metodo === "MERCADOPAGO" ? "Mercado Pago" : "seña pendiente"}</span>
          <span>Código <b style={{ color: "var(--fg-suave)" }}>{turno.codigo}</b></span>
          <span>Total {pesos(turno.servicio?.precio ?? 0)}</span>
          <span>Seña {pesos(turno.sena_monto)}</span>
        </div>

        <p className="status-info mt-4">{info.detalle}</p>

        {turno.estado === "PENDIENTE" && (
          <div className="card p-4 mt-4">
            {turno.metodo !== "TRANSFERENCIA" && process.env.MP_ACCESS_TOKEN && (
              <form action="/api/pago/mercadopago" method="post">
                <input type="hidden" name="id_turno" value={turno.id} />
                <button type="submit" className="btn btn-pri btn-block">PAGAR SEÑA CON MERCADO PAGO</button>
                <p className="muted mt-2 text-center">Se confirma solo cuando entra el pago.</p>
              </form>
            )}
            <div className="status-info mt-3">
              <p className="muted" style={{ letterSpacing: "0.2em", fontSize: 10, fontWeight: 600 }}>TRANSFERENCIA</p>
              <p className="text-sm mt-1 break-all">{cfg.alias_cbu}</p>
            </div>
          </div>
        )}

        <div className="res-actions flex-wrap">
          <a
            href={`https://wa.me/${wa}?text=${waMsg}`}
            target="_blank"
            rel="noreferrer"
            className="link-wa"
          >
            <IconoWa tam={14} /> AVISAR POR WHATSAPP
          </a>
          {info.cancelable && <CancelarReserva idTurno={turno.id} />}
        </div>
      </div>
    </main>
  );
}

// evita warning de variable sin usar por el formateador original
void formatFecha;

