type ClaveConfig =
  | "marca" | "marca_sufijo" | "kicker"
  | "hero_titulo" | "hero_acento" | "hero_texto" | "hero_tag"
  | "sobre_titulo" | "sobre_p1" | "sobre_p2" | "sobre_stats"
